    @Test public void continuousOwnerAllowsOnlyItsExactPreparedConfigAndRejectsOtherUnknownOrLeaseForgery()throws Exception {
        var app=RuntimeEnvironment.getApplication();var host=new dev.pocketengine.features.FeatureHost(event->{},tasks,()->false);var remote=dev.pocketengine.features.remote.HarnessGatewayRemoteFixture.pairForTest(new dev.pocketengine.features.FeatureContext(app,new dev.pocketengine.store.SettingsStore(app),new dev.pocketengine.store.SecretVault(app),event->{}),PAIRED,"computer",info.getString("baseUrl"));host.register(remote);String child=nativeRemoteChild(remote);var owner=tasks.issueHarnessGatewayConfigurationOwner(control,child);
        bridge=NativeHarnessGatewayBridge.forTask(tasks,control,()->model,(path,body)->{throw new AssertionError("unstarted native control fixture cannot dispatch");},"fixture",info.getString("environmentBinding"),"fixture-codex",dev.pocketengine.runtime.models.ModelRoutePlan.configurationDigest(model),System.currentTimeMillis()+45000,owner);
        var configuration=bridge.configurationFor(child);JSONObject source=tasks.remoteOwnerTarget(child),target=new JSONObject().put("environmentId","fixture").put("environmentBinding",info.getString("environmentBinding")).put("bindingId","fixture-codex"),probe=call("/v1/harnesses/probe",target),request=configuration.view();for(String key:new String[]{"environmentId","environmentBinding"})request.put(key,target.get(key));request.put("identityDigest",probe.getString("identityDigest")).put("taskId",child).put("runId",source.getString("runId")).put("epoch",source.getInt("coordinatorEpoch"));
        JSONObject prepared=tasks.prepareHarnessConfigOperation(child,source,request,probe,null,configuration);String operation=prepared.getString("operationId");owner.checkCurrent();configuration.checkCurrent();assertThrows(SecurityException.class,()->tasks.prepareHarnessConfigOperation(child,source,request,probe,null));
        // Adversarial non-billing SQL control rows only. No grant/usage/budget/owner proof is mocked.
        for(String tool:new String[]{"remote_approval","harness_config"}){String other=UUID.randomUUID().toString();android.content.ContentValues row=new android.content.ContentValues();row.put("operation_id",other);row.put("task_id",child);row.put("run_id",source.getString("runId"));row.put("tool",tool);row.put("arguments","{}");row.put("state",tool.equals("remote_approval")?"remote_approval_unknown":"unknown");row.put("created_at",System.currentTimeMillis());db().insertOrThrow("operations",null,row);assertThrows(SecurityException.class,owner::checkCurrent);android.content.ContentValues settled=new android.content.ContentValues();settled.put("state","receipt");assertEquals(1,db().update("operations",settled,"operation_id=?",new String[]{other}));owner.checkCurrent();}
        String raw;try(Cursor row=db().rawQuery("SELECT arguments FROM operations WHERE operation_id=?",new String[]{operation})){assertTrue(row.moveToFirst());raw=row.getString(0);}JSONObject changed=new JSONObject(raw);changed.getJSONObject("request").put("endpointLeaseRef","forged-other-lease");android.content.ContentValues values=new android.content.ContentValues();values.put("arguments",changed.toString());assertEquals(1,db().update("operations",values,"operation_id=?",new String[]{operation}));assertThrows(SecurityException.class,configuration::checkCurrent);values.put("arguments",raw);assertEquals(1,db().update("operations",values,"operation_id=?",new String[]{operation}));owner.checkCurrent();assertEquals(0,calls.get());assertEquals(0,tasks.inferenceUsage(task.getString("id")).getJSONArray("receipts").length());remote.close();host.close();
    }
    private SQLiteDatabase db()throws Exception {var field=TaskStore.class.getDeclaredField("db");field.setAccessible(true);return (SQLiteDatabase)field.get(tasks);}
    private void awaitClaims(String state,int count)throws Exception {long end=System.currentTimeMillis()+5000;while(true){try(Cursor rows=db().rawQuery("SELECT count(*) FROM harness_gateway_claims WHERE lease_id=? AND state=?",new String[]{bridge.leaseId(),state})){assertTrue(rows.moveToFirst());if(rows.getInt(0)==count)return;}if(System.currentTimeMillis()>=end)fail("original native claim did not reach "+state);Thread.sleep(10);}}
    private void verifyOriginalLedger()throws Exception {
        awaitClaims("COMPLETE",1);assertNull(peerFailure.get());assertEquals(1,calls.get());JSONObject usage=tasks.inferenceUsage(task.getString("id"));JSONArray receipts=usage.getJSONArray("receipts");assertEquals(1,receipts.length());JSONObject receipt=receipts.getJSONObject(0);assertEquals("RELAY",receipt.getJSONObject("context").getString("purpose"));assertEquals(task.getString("runId"),receipt.getJSONObject("context").getString("runId"));assertEquals("COMPLETED",receipt.getString("outcome"));
        try(Cursor rows=db().rawQuery("SELECT state,request_digest FROM harness_gateway_claims WHERE lease_id=?",new String[]{bridge.leaseId()})){assertTrue(rows.moveToFirst());assertEquals("COMPLETE",rows.getString(0));assertTrue(rows.getString(1).matches("[a-f0-9]{64}"));assertFalse(rows.moveToNext());}
        assertEquals(7,db().getVersion());try(Cursor rows=db().rawQuery("SELECT count(*) FROM leases WHERE resource_id='phone.local'",null)){assertTrue(rows.moveToFirst());assertEquals(0,rows.getInt(0));}
    }
